function countriesPage(){
 root.innerHTML=header({kicker:'Countries & cultures',title:'Every place has a <span class="accent">different story.</span>',desc:'Browse dedicated national profiles. Research-rich guides are clearly separated from starter profiles awaiting deeper local verification.',crumb:[['Countries']]})+
 `<section class="section"><div class="page-width"><div class="filters"><div class="filter-control" style="flex:2"><label for="country-search">Search country, tradition, or region</label><input id="country-search" type="search" placeholder="Try Italy, FKK or Asia…" autocomplete="off"></div><div class="filter-control"><label for="country-region">Region</label><select id="country-region">${regions.map(r=>`<option>${r}</option>`).join('')}</select></div><div class="filter-control"><label for="country-depth">Research level</label><select id="country-depth"><option value="all">All profiles</option><option value="detailed">Researched guides</option><option value="starter">Starter guides</option></select></div></div><div class="results-bar"><span id="country-count"></span><span>🌿 More countries will be added over time</span></div><div class="cards-grid" id="countries-results"></div><div class="notice" style="margin-top:25px"><strong>Why some guides say “starter”</strong>We prefer honest, incomplete coverage to invented beach permissions. Starter profiles link to the international federation directory but deliberately avoid unverified venue and legal claims.</div></div></section>`;
 const refresh=()=>{const q=document.getElementById('country-search').value.toLowerCase().trim(),r=document.getElementById('country-region').value,depth=document.getElementById('country-depth').value;
 const list=countries.filter(c=>(!q||[c.name,c.culture,c.label,c.region].join(' ').toLowerCase().includes(q))&&(r==='All regions'||c.region===r)&&(depth==='all'||c.depth===depth));
 document.getElementById('country-count').textContent=filteredMsg(list.length,'country profiles');document.getElementById('countries-results').innerHTML=list.length?list.map(countryCard).join(''):'<div class="empty">🌻 No countries found. Try a broader search.</div>';};
 ['country-search','country-region','country-depth'].forEach(id=>document.getElementById(id).addEventListener(id==='country-search'?'input':'change',refresh));refresh();
}
function countryPage(code){const c=byCode[code];if(!c)return notFound();const places=spots.filter(s=>s.country===code);
 const sourceLinks=c.sources.map(([t,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(t)}</a>`).join('');
 const mapMarkup=places.length?section({title:'Places on the map',desc:`${places.length} documented ${places.length===1?'entry':'entries'} for ${esc(c.name)}. The red alert marker denotes a restriction, not an invitation to visit.`,content:`<div class="cards-grid">${places.map(placeCard).join('')}</div>`}):`<section class="section-tight"><div class="page-width"><div class="notice"><strong>🧭 No site-level entries yet</strong>This country page is a research starting point. We have not independently verified a specific beach or resort here, so none is presented as recommended.</div></div></section>`;
 root.innerHTML=`<section class="page-hero"><div class="page-width">${bread([['Countries','#/countries'],[c.name]])}<span class="eyebrow">Country field guide · ${esc(c.region)}</span><div class="title-row"><span class="big-flag">${c.flag}</span><h1>${esc(c.name)}</h1></div><p>${esc(c.label)} — a respectful introduction to local traditions, practical travel considerations and what is (and is not) verified.</p>${dots([[c.depth==='detailed'?'Researched guide':'Starter profile',c.depth==='detailed'?'':'slate'],[c.region,'lav']])}</div></section>
 <section class="section"><div class="page-width"><div class="detail-layout"><div><article class="panel detail-card"><h3>🌸 A little cultural history</h3><p>${esc(c.culture)}</p></article>
 <article class="panel detail-card"><h3>⚖️ Law & local boundaries</h3><p>${esc(c.law)}</p><div class="notice"><strong>Legal context, not a legal verdict</strong>Check the local authority, the specific venue and current notices. National guides cannot replace on-the-ground rules.</div></article>
 <article class="panel detail-card"><h3>☀️ Topfree sunbathing</h3><span class="pill ${topColor[c.toplessStatus]}">${topNames[c.toplessStatus]}</span><p>${esc(c.topless)}</p><a class="link-more" href="#/topless">Read our topless guide</a></article>
 <article class="panel detail-card"><h3>🌿 Traveller’s note</h3><p>${esc(c.tip)}</p><div class="note-inline">✿ Written from linked resources, not from a claimed personal visit.</div></article></div>
 <aside class="detail-side"><div class="panel"><div class="label">At a glance</div><h3 style="margin:7px 0">${c.flag} ${esc(c.name)}</h3><p class="muted" style="font-size:13px">Region: <strong>${esc(c.region)}</strong></p><p class="muted" style="font-size:13px">Coverage: <strong>${c.depth==='detailed'?'Verified reference notes':'Research pending'}</strong></p><p class="muted" style="font-size:13px">Mapped entries: <strong>${places.length}</strong></p><div class="line"></div><div class="label">Source links</div><div class="source-links">${sourceLinks}</div><div class="line"></div><p class="countline">Editorially checked: ${esc(D.reviewed)}</p><a class="btn btn-small btn-light" href="#/atlas" style="width:100%;margin-top:8px">🗺️ Explore world atlas</a></div></aside></div></div></section>${mapMarkup}`;if(window.NATURIA_PLACE_PHOTOS)window.NATURIA_PLACE_PHOTOS.mountCards(places,root);
}
function placesPage(){
 root.innerHTML=header({kicker:'Discover real places',title:'Beaches, stays & <span class="accent">coastal escapes.</span>',desc:'Search a carefully labelled list of places with descriptions, practical notes and the source that supports each entry. No fabricated star ratings or personal reviews.',crumb:[['Beaches & stays']]})+
 `<section class="section"><div class="page-width"><div class="filters"><div class="filter-control" style="flex:2"><label for="place-search">Search places</label><input type="search" id="place-search" placeholder="Try a beach, city or resort…" autocomplete="off"></div><div class="filter-control"><label for="place-country">Country</label><select id="place-country"><option value="all">All countries</option>${countries.filter(c=>spots.some(p=>p.country===c.code)).map(c=>`<option value="${c.code}">${c.flag} ${esc(c.name)}</option>`).join('')}</select></div><div class="filter-control"><label for="place-type">Place type</label><select id="place-type"><option value="all">Every type</option><option value="beach">Beaches</option><option value="resort">Resorts / camps</option><option value="alert">Legal alerts</option><option value="wellness">Traditional bathing (not naturism)</option></select></div><div class="filter-control"><label for="place-status">Evidence label</label><select id="place-status"><option value="all">Every status</option><option value="recognised">Officially listed</option><option value="managed">Managed operator</option><option value="traditional">Traditional use</option><option value="caution">Legal alert</option></select></div></div><div class="results-bar"><span id="place-count"></span><a class="link-more" href="#/atlas">Open world map</a></div><div class="cards-grid" id="places-results"></div><div class="notice" style="margin-top:26px"><strong>What about reviews?</strong>These are desk-researched editorial descriptions, not reviews written by visitors. We do not assign scores or invent personal experiences. Primary-source links are included on every card.</div></div></section>`;
 const refresh=()=>{const q=document.getElementById('place-search').value.toLowerCase().trim(),cc=document.getElementById('place-country').value,type=document.getElementById('place-type').value,status=document.getElementById('place-status').value;
 const list=spots.filter(p=>(!q||[p.name,p.area,p.summary,byCode[p.country].name].join(' ').toLowerCase().includes(q))&&(cc==='all'||p.country===cc)&&(type==='all'||p.type===type)&&(status==='all'||p.status===status));
 document.getElementById('place-count').textContent=filteredMsg(list.length,'directory entries');document.getElementById('places-results').innerHTML=list.length?list.map(placeCard).join(''):'<div class="empty">🌼 No matching locations. Try a different filter.</div>';if(window.NATURIA_PLACE_PHOTOS)window.NATURIA_PLACE_PHOTOS.mountCards(list,document.getElementById('places-results'));};
 ['place-search','place-country','place-type','place-status'].forEach(id=>document.getElementById(id).addEventListener(id==='place-search'?'input':'change',refresh));refresh();
}
