 const menu=document.getElementById('site-nav');menu.classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.querySelector('.nav-more').classList.remove('open');
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route||(route==='country'&&a.dataset.nav==='countries')||(route==='place'&&a.dataset.nav==='places')));
 const extraPages=window.NATURIA_SECTIONS||{};
 if(typeof extraPages[route]==='function') extraPages[route](decodeURIComponent(path[1]||''));
 else if(route==='journal'&&window.NATURIA_JOURNAL_RENDER) window.NATURIA_JOURNAL_RENDER();
 else if(route==='home')home();else if(route==='atlas')atlasPage();else if(route==='countries')countriesPage();else if(route==='country')countryPage(decodeURIComponent(path[1]||'').toUpperCase());else if(route==='places')placesPage();else if(route==='place')placePage(decodeURIComponent(path[1]||''));else if(route==='etiquette')etiquette();else if(route==='topless')topless();else if(route==='laws')laws();else if(route==='history')history();else if(route==='resources')resources();else if(route==='contact')contact();else notFound();
 if(!extraPages[route] && route!=='journal' && window.NATURIA_EXTRA_DETAILS) window.NATURIA_EXTRA_DETAILS();
 document.querySelectorAll('#more-nav a').forEach(a=>{if(a.getAttribute('href')==='#/'+route) a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 window.scrollTo({top:0,behavior:'instant'});
